<script setup lang="ts">
import { COMPONENTS } from '~/domain/selectors'
definePageMeta({ layout: 'workspace' })
useHead({ title: 'Monitoring - UKIN PPG UNJ' })
const u = useUkin(), { error, message, act } = useOperationFeedback()
const period = ref(''), subject = ref(''), perspective = ref('Peserta')
const all = computed(() => u.user.value?.role === 'pengelola' ? u.operations.getMonitoring() : [])
const periods = computed(() => [...new Map(all.value.map(r => [r.periodId, r.periodName])).entries()])
const rows = computed(() => all.value.filter(r => (!period.value || r.periodId === period.value) && (!subject.value || r.subject === subject.value)))
const labels = { not_started: 'Belum dimulai', draft: 'Draf', final: 'Final' }
function download() { act(() => { const blob = new Blob([u.operations.exportMonitoring(period.value)], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'ukin-monitoring-fiktif.csv'; a.click(); URL.revokeObjectURL(url) }, 'CSV periode terpilih dibuat. Isinya data fiktif dan status, tanpa catatan internal.') }
</script>
<template>
  <div class="operations-page">
    <header><p class="eyebrow">PENGELOLA / MONITORING</p><h1>Satu proses, beberapa sudut pandang.</h1><p class="muted">Status dihitung dari paket, penugasan, dan penilaian yang tersimpan.</p></header>
    <section class="op-hero"><div class="op-metrics"><div><strong>{{ rows.length }}</strong><span>Peserta aktif</span></div><div><strong>{{ rows.filter(r => r.completeness === 'complete').length }}</strong><span>Paket lengkap</span></div><div><strong>{{ rows.filter(r => !r.problems.length).length }}</strong><span>Siap publikasi</span></div><div><strong>{{ rows.filter(r => r.moderation === 'open').length }}</strong><span>Moderasi terbuka</span></div></div><AppIcon name="grid" :size="50" /></section>
    <div class="op-grid"><label class="op-field">Periode<select v-model="period"><option value="">Semua periode yang dikelola</option><option v-for="[id, name] in periods" :key="id" :value="id">{{ name }}</option></select></label><label class="op-field">Bidang studi<select v-model="subject"><option value="">Semua bidang studi</option><option v-for="s in [...new Set(all.map(r => r.subject))]" :key="s">{{ s }}</option></select></label></div>
    <nav class="op-tabs" aria-label="Sudut pandang monitoring"><button v-for="tab in ['Peserta', 'Dokumen', 'Penguji', 'Nilai', 'Wawancara']" :key="tab" :aria-pressed="perspective === tab" @click="perspective = tab">{{ tab }}</button></nav>
    <p v-if="error" class="op-error" role="alert">{{ error }}</p><p v-if="message" class="op-success" role="status">{{ message }}</p>
    <section class="op-panel"><div class="op-row"><h2>{{ perspective }}</h2><UButton variant="soft" @click="download">Ekspor CSV periode</UButton></div><p class="op-caption">CSV mengikuti filter periode; filter bidang studi berlaku pada tampilan. Skor ditampilkan per komponen setelah dua final lengkap, tanpa nilai gabungan atau ambang kelulusan.</p>
      <div class="op-table-wrap"><table class="op-table"><thead><tr><th>Peserta / periode</th><th v-if="perspective === 'Peserta'">Alur saat ini</th><th v-if="perspective === 'Dokumen'">Paket dan bukti</th><th v-if="['Penguji', 'Nilai'].includes(perspective)">Dosen dan guru</th><th v-if="perspective === 'Wawancara'">Wawancara</th><th>Tindak lanjut</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{ r.participant }}</strong><small>{{ r.subject }} / {{ r.periodName }}</small></td><td v-if="perspective === 'Peserta'"><span class="op-tag">{{ r.publication }}</span><small>Kelengkapan: {{ r.completeness }}</small><small>Moderasi: {{ r.moderation }}</small></td><td v-if="perspective === 'Dokumen'">{{ r.evidenceVersion ? `Paket v${r.evidenceVersion}` : 'Belum dikirim' }}<small>{{ r.packageStatus }} / {{ r.completeness }}</small><NuxtLink v-if="r.evidenceVersionId" :to="{ path: '/app/bukti', query: { id: r.evidenceVersionId } }">Buka bukti</NuxtLink></td><td v-if="['Penguji', 'Nilai'].includes(perspective)"><p v-if="!r.examiners.length">Belum ditugaskan</p><div v-for="e in r.examiners" :key="e.id"><strong>{{ e.kind }}: {{ e.name }}</strong><small>{{ labels[e.status] }}{{ e.revisionDraft ? ' revisi' : '' }} / {{ e.issues }} kendala{{ e.active ? '' : ' / Akun nonaktif' }}</small><template v-if="perspective === 'Nilai'"><small v-for="s in e.scores" :key="s.id">{{ COMPONENTS.find(c => c.id === s.id)?.label }}: {{ s.score }}/{{ s.maximum }}</small><small v-if="!e.scores.length">Menunggu dua final terkini</small></template></div></td><td v-if="perspective === 'Wawancara'">{{ r.interview }}</td><td><NuxtLink :to="{ path: '/app/publikasi', query: { id: r.id } }">Tinjau publikasi</NuxtLink><small v-for="p in r.problems" :key="p" style="white-space:normal;max-width:280px">{{ p }}</small></td></tr></tbody></table></div><p v-if="!rows.length" class="op-empty">Tidak ada peserta pada filter ini.</p>
    </section>
  </div>
</template>
